'use strict';
const fs=require('node:fs'),path=require('node:path'),{execFileSync}=require('node:child_process');
const Bridge=require('../../src/bridge-controller');const {CapabilityHost}=require('../../src/capability-host');const {HostExecutor}=require('../../src/host-exec');const {EXECUTABLES}=require('../../src/capability-mac');
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function fixture(t,{realClaude=false,opencode}={}){
 const root=fs.realpathSync(fs.mkdtempSync('/private/tmp/mission2-')),home=realClaude?require('node:os').homedir():path.join(root,'home'),repo=path.join(root,'repo'),dataDir=path.join(root,'data');fs.mkdirSync(repo);fs.mkdirSync(dataDir);if(!realClaude)fs.mkdirSync(home);
 fs.mkdirSync(path.join(repo,'tests'));fs.mkdirSync(path.join(repo,'.vscode'));
 fs.writeFileSync(path.join(repo,'fixture.txt'),'alpha\n');fs.writeFileSync(path.join(repo,'tests/fixture.test.cjs'),"const assert=require('node:assert/strict');assert.equal(require('node:fs').readFileSync('fixture.txt','utf8'),'beta\\n');\n");
 fs.writeFileSync(path.join(repo,'.vscode/tasks.json'),JSON.stringify({version:'2.0.0',tasks:[{label:'diff-check',type:'process',command:'git',args:['diff','--check']},{label:'fixture-test',type:'process',command:'node',args:['--test','tests/fixture.test.cjs']}]}));
 const git=args=>execFileSync('/usr/bin/git',['-C',repo,...args],{stdio:'pipe'});git(['init','-q']);git(['add','.']);git(['-c','user.name=Fixture','-c','user.email=fixture@example.invalid','-c','core.hooksPath=/dev/null','-c','commit.gpgSign=false','commit','-qm','fixture baseline']);
 const fake=path.join(root,'claude');fs.writeFileSync(fake,`#!${process.execPath}\nconst fs=require('node:fs');const args=process.argv.slice(2);if(args[0]==='--version'){console.log('1.0 fixture');process.exit(0);}if(args[0]==='auth'){console.log(JSON.stringify({loggedIn:true,authMethod:'claude.ai',subscriptionType:'pro'}));process.exit(0);}const envelope=JSON.parse(args[1]);fs.appendFileSync(${JSON.stringify(path.join(root,'calls'))},'call\\n');let result;if(envelope.objective.includes('DECISION')&&!envelope.continuation)result={needs_operator:true,question:'Choose a strategy',options:[{id:'A',label:'A',recommended:true},{id:'B',label:'B'}],allow_free_text:true};else{fs.writeFileSync('fixture.txt','beta\\n');if(envelope.allowed_files.includes('strategy.txt'))fs.writeFileSync('strategy.txt',envelope.continuation.answer.option_id+'\\n');result={status:'completed',summary:'Fixture edited',changed_files:['fixture.txt'],tests:[{status:'passed',command:'claim only'}],memory_candidates:[{type:'project_fact',subject:'Fixture result',content:'Fixture uses beta',confidence:90}]};}console.log(JSON.stringify({is_error:false,result:JSON.stringify(result)}));`,{mode:0o700});
 class Exec extends HostExecutor{
   constructor(){super({home,allowed:[...EXECUTABLES,'/usr/bin/git',process.execPath,fake,...(realClaude?[path.join(home,'.local/bin/claude')]:[])]});}
   resolveFirst(candidates){if(candidates.some(c=>c.includes('/claude')))return realClaude?path.join(home,'.local/bin/claude'):fake;if(candidates.some(c=>/\/node$/.test(c)))return process.execPath;if(candidates.includes('/usr/bin/git'))return'/usr/bin/git';return null;}
 }
 const executor=new Exec();let host=new CapabilityHost({dataDir,home,exec:executor,env:{},bridgeRoot:path.resolve(__dirname,'../..'),probeHttp:async()=>false,localServicesPath:path.join(root,'none')});
 const profile=path.join(root,'profile');fs.mkdirSync(profile);fs.writeFileSync(path.join(profile,'settings.json'),JSON.stringify({defaultProvider:'fixture',defaultModel:'fixture'}));
 let bridge=await new Bridge({slack:{env:{}},dataDir,sourceProfile:profile,capabilityHost:host,allowFixtureWorker:true,opencode,executable:path.join(__dirname,'fake-pi.cjs')}).initialize();host.saveTask=t=>bridge.tasks.save(t);
 let inference=0;bridge.localOllamaBroker.proxy=()=>{inference++;throw Error('Inference must not be called');};bridge.prompt=()=>{inference++;throw Error('Pi inference must not be called');};
 const project=bridge.projects.createProject({name:'Fixture project',repositories:[repo]}),goal=bridge.projects.createGoal({projectId:project.projectId,name:'Fixture goal'});
 const create=(extra={})=>bridge.missions.create({request_id:require('node:crypto').randomUUID(),project_id:project.projectId,goal_id:goal.goalId,objective:'Change fixture.txt from alpha to beta. Make its test pass.',workspace:repo,allowed_files:['fixture.txt'],criteria:[{id:'expected_file',type:'exact_file',path:'fixture.txt',content:'beta\n'}],verification:{diff_check:'diff-check',tests:['fixture-test'],syntax:[]},...extra});
 const settle=async(id,state='awaiting_acceptance')=>{for(let n=0;n<(realClaude?6000:300);n++){await bridge.missions.tick();const m=bridge.missions.detail(id);if(m.state===state)return m;if(['blocked','needs_rework'].includes(m.state)&&m.state!==state)throw Error(JSON.stringify({state:m.state,reason:m.reason,verifications:m.verifications}));await wait(25);}throw Error('Mission did not settle: '+bridge.missions.detail(id).state);};
 t.after(async()=>{await bridge.missions.close();host.shutdown();await Promise.race([Promise.all([...host.jobs.jobs.values()].map(j=>j.done)),wait(6500)]);await bridge.shutdown();if(!realClaude)fs.rmSync(root,{recursive:true,force:true});});
 return{root,repo,get bridge(){return bridge;},get host(){return host;},reopen:async()=>{await bridge.shutdown();host=new CapabilityHost({dataDir,home,exec:executor,env:{},bridgeRoot:path.resolve(__dirname,'../..'),probeHttp:async()=>false,localServicesPath:path.join(root,'none')});bridge=await new Bridge({slack:{env:{}},dataDir,sourceProfile:profile,capabilityHost:host,allowFixtureWorker:true,opencode,executable:path.join(__dirname,'fake-pi.cjs')}).initialize();host.saveTask=t=>bridge.tasks.save(t);bridge.localOllamaBroker.proxy=()=>{inference++;throw Error('Inference must not be called');};bridge.prompt=()=>{inference++;throw Error('Pi inference must not be called');};},create,settle,inference:()=>inference,calls:()=>fs.existsSync(path.join(root,'calls'))?fs.readFileSync(path.join(root,'calls'),'utf8').trim().split('\n').length:0};
}
module.exports={fixture,wait};
